# PY1-C9: predict first.
def classify_port(port):
    if port < 0 or port > 65535:
        return "invalid"
    if port < 1024:
        return "well-known"
    if port < 49152:
        return "registered"
    return "dynamic"

print(classify_port(22), classify_port(8080), classify_port(70000))
result = classify_port(443)
print(result)

def is_private_ip(ip):
    return ip.startswith("10.") or ip.startswith("192.168.")

print(is_private_ip("192.168.1.5"), is_private_ip("203.0.113.9"))
