# PY1-C11: a password-strength checker, v0. Rules (each worth 1 point): length >= 12; has a lowercase letter;
# has an uppercase letter; has a digit; has a symbol; is not in the tiny common list. Print the score and the missing rules.
# NEVER use a real password of yours here - this is a toy on test strings.
COMMON = ["password", "123456", "qwerty", "letmein", "iloveyou"]

def score(pw):
    points = 0
    missing = []
    if len(pw) >= 12:
        points += 1
    else:
        missing.append("12+ characters")
    # add: lowercase, uppercase, digit, symbol (use any(c.islower() for c in pw) etc.), not in COMMON
    return points, missing

for test in ["password", "Tr0ub4dor&3", "correct horse battery staple"]:
    p, m = score(test)
    print(f"{test!r}: {p}/6 missing={m}")

# PY2-C2: predict first (this one runs in the editor).
def parse_port(text):
    try:
        port = int(text)
    except ValueError:
        raise ValueError(f"not a number: {text!r}")
    if not 0 <= port <= 65535:
        raise ValueError(f"out of range: {port}")
    return port

for t in ["22", "70000", "abc", "443"]:
    try:
        print("ok", parse_port(t))
    except ValueError as e:
        print("rejected:", e)
    finally:
        print("checked", t)

